func (s *APIV1Service) CreateMemoComment(ctx context.Context, request *v1pb.CreateMemoCommentRequest) (*v1pb.Memo, error) {
	memoUID, err := ExtractMemoUIDFromName(request.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid memo name: %v", err)
	}
	relatedMemo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get memo")
	}
	if relatedMemo == nil {
		return nil, status.Errorf(codes.NotFound, "memo not found")
	}

	// Check memo visibility before allowing comment.
	user, err := s.fetchCurrentUser(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get user")
	}
	if user == nil {
		return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
	}
	if relatedMemo.Visibility == store.Private && relatedMemo.CreatorID != user.ID && !isSuperUser(user) {
		return nil, status.Errorf(codes.PermissionDenied, "permission denied")
	}
	if request.Comment == nil {
		return nil, status.Errorf(codes.InvalidArgument, "comment is required")
	}

	comment, ok := proto.Clone(request.Comment).(*v1pb.Memo)
	if !ok {
		return nil, status.Errorf(codes.Internal, "failed to clone memo comment")
	}
	comment.Visibility = convertVisibilityFromStore(relatedMemo.Visibility)

	// Create the memo comment first; suppress the generic memo.created SSE event
	// since CreateMemoComment broadcasts memo.comment.created for the parent instead.
	memoComment, err := s.CreateMemo(withSuppressMentionNotifications(withSuppressSSE(ctx)), &v1pb.CreateMemoRequest{
		Memo:   comment,
		MemoId: request.CommentId,
	})
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to create memo")
	}
	memoUID, err = ExtractMemoUIDFromName(memoComment.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid memo name: %v", err)
	}
	memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get memo")
	}

	// Build the relation between the comment memo and the original memo.
	_, err = s.Store.UpsertMemoRelation(ctx, &store.MemoRelation{
		MemoID:        memo.ID,
		RelatedMemoID: relatedMemo.ID,
		Type:          store.MemoRelationComment,
	})
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to create memo relation")
	}

	ExcludeComments: true,
	ExcludeContent:  true,
	RowStatus:       &rowStatus,
}

currentUser, err := s.fetchCurrentUser(ctx)
if err != nil {
	return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
}

if request.Filter != "" {
	if err := s.validateFilter(ctx, request.Filter); err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid filter: %v", err)
	}
	memoFind.Filters = append(memoFind.Filters, request.Filter)
}

if request.State == v1pb.State_ARCHIVED {
	// Archived memos are only visible to their creator.
	if currentUser == nil {
		return &v1pb.ListAllUserStatsResponse{}, nil
	}
	memoFind.CreatorID = &currentUser.ID
} else if currentUser == nil {
	memoFind.VisibilityList = []store.Visibility{store.Public}
} else {
	if memoFind.CreatorID == nil {
		filter := fmt.Sprintf(`creator_id == %d || visibility in ["PUBLIC", "PROTECTED"]`, currentUser.ID)
		memoFind.Filters = append(memoFind.Filters, filter)
	} else if *memoFind.CreatorID != currentUser.ID {
		memoFind.VisibilityList = []store.Visibility{store.Public, store.Protected}
	}
}

userMemoStatMap := make(map[int32]*v1pb.UserStats)
pinnedMemoIDsByUserID := make(map[int32][]int32)
limit := 1000
offset := 0
memoFind.Limit = &limit
memoFind.Offset = &offset

for {
	memos, err := s.Store.ListMemos(ctx, memoFind)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to list memos: %v", err)
	}
	if len(memos) == 0 {
		break
	}

	for _, memo := range memos {
		// Initialize user stats if not exists
		if _, exists := userMemoStatMap[memo.CreatorID]; !exists {
			userMemoStatMap[memo.CreatorID] = &v1pb.UserStats{
				Name:                  "",
				TagCount:              make(map[string]int32),
				MemoCreatedTimestamps: []*timestamppb.Timestamp{},
				MemoUpdatedTimestamps: []*timestamppb.Timestamp{},
				PinnedMemos:           []string{},
				MemoTypeStats: &v1pb.UserStats_MemoTypeStats{
					LinkCount: 0,
					CodeCount: 0,
					TodoCount: 0,
					UndoCount: 0,
				},
			}
		}

		stats := userMemoStatMap[memo.CreatorID]

		stats.MemoCreatedTimestamps = append(stats.MemoCreatedTimestamps, timestamppb.New(time.Unix(memo.CreatedTs, 0)))
		stats.MemoUpdatedTimestamps = append(stats.MemoUpdatedTimestamps, timestamppb.New(time.Unix(memo.UpdatedTs, 0)))

		// Count memo stats
		stats.TotalMemoCount++

		// Count tags and other properties
		if memo.Payload != nil {
			for _, tag := range memo.Payload.Tags {
				stats.TagCount[tag]++
			}
			if memo.Payload.Property != nil {
				if memo.Payload.Property.HasLink {
					stats.MemoTypeStats.LinkCount++
				}
				if memo.Payload.Property.HasCode {
					stats.MemoTypeStats.CodeCount++
				}
				if memo.Payload.Property.HasTaskList {
					stats.MemoTypeStats.TodoCount++
				}
				if memo.Payload.Property.HasIncompleteTasks {
					stats.MemoTypeStats.UndoCount++
				}
			}
		}

		// Track pinned memos
		if memo.Pinned {
			pinnedMemoIDsByUserID[memo.CreatorID] = append(pinnedMemoIDsByUserID[memo.CreatorID], memo.ID)

		CreatorID:  relatedMemo.CreatorID,
	})

	return memoComment, nil
}

